students = [{'name': 'Alice', 'score': 90}, {'name': 'Bob', 'score': 75}, {'name': 'Carol', 'score': 85}]
for student in students:
    if student['score'] > 80:
        print(student['name'])

classes = {'math': [90, 85, 92], 'english': [78, 88, 95]}
for subject, scores in classes.items():
    average = sum(scores) / len(scores)
    print(f'{subject}: {average:.1f}')

people = [{'name': 'Bob', 'age': 30}, {'name': 'Alice', 'age': 25}, {'name': 'Carol', 'age': 28}]
for person in sorted(people, key=lambda p: p['age']):
    print(person['name'])

