    {'name': 'Bob', 'score': 75},
]
for s in students:
    print(f"{s['name']} scored {s['score']}")

classes = {'math': [90, 85, 92], 'english': [78, 88, 95]}
for subject, scores in classes.items():
    print(f'{subject}: {sum(scores) / len(scores):.1f}')

people = [{'name': 'Bob', 'age': 30}, {'name': 'Alice', 'age': 25}]
